export const AGENT_LUA = "--[[\n    OneEight External Hub - Master Modular Client Agent\n    Version: 3.1.0 (CDID Main Menu & Server Gateway Support)\n--]]\n\nif _G.OE_ExternalRunning then\n    print(\"[OE-External] Instance sebelumnya terdeteksi, membersihkan...\")\n    _G.OE_ExternalRunning = false\n    if _G.OE_ExternalSocket then\n        pcall(function() _G.OE_ExternalSocket:Close() end)\n    end\n    task.wait(1)\nend\n\n_G.OE_ExternalRunning = true\n\nlocal HttpService = game:GetService(\"HttpService\")\nlocal Players = game:GetService(\"Players\")\nlocal TeleportService = game:GetService(\"TeleportService\")\nlocal LocalPlayer = Players.LocalPlayer\n\n-- ============================================================================\n-- MODULAR INTERNAL VFS\n-- ============================================================================\nlocal Modules = {}\n\nModules[\"core/safety\"] = function()\n--[[\n    OneEight External Hub - Core Safety & Kick Detection Engine\n    Handles:\n    1. Anti-AFK (20-minute idle bypass)\n    2. Real-time Kick / Disconnect detection (GuiService & RobloxPromptGui)\n    3. Auto-Rejoin subsystem with queue_on_teleport\n--]]\n\nlocal Safety = {}\nlocal Players = game:GetService(\"Players\")\nlocal GuiService = game:GetService(\"GuiService\")\nlocal CoreGui = game:GetService(\"CoreGui\")\nlocal TeleportService = game:GetService(\"TeleportService\")\nlocal VirtualUser = game:GetService(\"VirtualUser\")\nlocal LocalPlayer = Players.LocalPlayer\n\nSafety.AutoRejoin = true\nSafety.RejoinDelay = 5\nSafety.IsKicked = false\nSafety.KickReason = nil\nSafety.OnKickedCallback = nil\n\n-- 1. Anti-AFK (Native VirtualUser simulation)\nfunction Safety.StartAntiAFK()\n    LocalPlayer.Idled:Connect(function()\n        pcall(function()\n            VirtualUser:CaptureController()\n            VirtualUser:ClickButton2(Vector2.zero)\n        end)\n    end)\nend\n\n-- 2. Trigger Kick Handler\nlocal function handleKick(reason)\n    if Safety.IsKicked then return end\n    Safety.IsKicked = true\n    Safety.KickReason = reason or \"Roblox Disconnected\"\n\n    warn(\"[OE-External Safety] DISCONNECT / KICK DETECTED: \" .. tostring(Safety.KickReason))\n\n    if Safety.OnKickedCallback then\n        pcall(Safety.OnKickedCallback, Safety.KickReason)\n    end\n\n    if Safety.AutoRejoin then\n        task.spawn(function()\n            print(string.format(\"[OE-External Safety] Auto-Rejoin aktif! Menghubungkan ulang dalam %d detik...\", Safety.RejoinDelay))\n            task.wait(Safety.RejoinDelay)\n            Safety.RejoinNow()\n        end)\n    end\nend\n\n-- 3. Install Kick & Error Dialog Listeners\nfunction Safety.InitKickDetector(onKickedCallback)\n    Safety.OnKickedCallback = onKickedCallback\n\n    -- Listener A: GuiService ErrorMessageChanged\n    pcall(function()\n        GuiService.ErrorMessageChanged:Connect(function(errMsg)\n            if errMsg and #errMsg > 0 then\n                handleKick(errMsg)\n            end\n        end)\n    end)\n\n    -- Listener B: CoreGui RobloxPromptGui promptOverlay\n    pcall(function()\n        local promptGui = CoreGui:WaitForChild(\"RobloxPromptGui\", 10)\n        local overlay = promptGui and promptGui:WaitForChild(\"promptOverlay\", 10)\n        if overlay then\n            overlay.ChildAdded:Connect(function(child)\n                if child.Name == \"ErrorPrompt\" then\n                    local msgLabel = child:FindFirstChild(\"ErrorMessage\", true)\n                    local msg = msgLabel and msgLabel.Text or \"Roblox Disconnected\"\n                    handleKick(msg)\n                end\n            end)\n        end\n    end)\n\n    -- Listener C: Teleport Failures\n    pcall(function()\n        TeleportService.TeleportInitFailed:Connect(function(player, teleportResult, errMsg)\n            if player == LocalPlayer then\n                handleKick(\"Teleport Gagal: \" .. tostring(errMsg or teleportResult))\n            end\n        end)\n    end)\nend\n\n-- 4. Rejoin Server Now\nfunction Safety.RejoinNow(loaderUrl)\n    loaderUrl = loaderUrl or \"https://externalhub.oneeight-project18.workers.dev/loader\"\n    local queue_teleport = (syn and syn.queue_on_teleport) or queue_on_teleport or (fluxus and fluxus.queue_on_teleport)\n    if queue_teleport then\n        pcall(function()\n            queue_teleport(string.format([[\n                task.wait(4)\n                loadstring(game:HttpGet(\"%s\"))()\n            ]], loaderUrl))\n        end)\n    end\n\n    pcall(function()\n        TeleportService:Teleport(game.PlaceId, LocalPlayer)\n    end)\nend\n\nreturn Safety\n\nend\n\nModules[\"games/base_game\"] = function()\n--[[\n    OneEight External Hub - Base Game Module Contract\n    All game modules (CDID, DDS, etc.) must adhere to this interface contract.\n--]]\n\nlocal BaseGame = {}\nBaseGame.__index = BaseGame\n\nfunction BaseGame.New(gameId, gameName, currencyUnit, metricUnit)\n    local self = setmetatable({}, BaseGame)\n    self.GameId = gameId or \"generic\"\n    self.GameName = gameName or \"Generic Game\"\n    self.CurrencyUnit = currencyUnit or \"Cash\"\n    self.MetricUnit = metricUnit or \"Trips\"\n    self.IsFarming = false\n    self.CurrentStatus = \"READY\"\n    return self\nend\n\nfunction BaseGame:Init(coreContext)\n    -- Abstract method to be overridden\n    self.Context = coreContext\nend\n\nfunction BaseGame:HandleCommand(action, payload)\n    -- Abstract method to be overridden\n    -- Return boolean indicating whether command was handled\n    return false\nend\n\nfunction BaseGame:GetTelemetry()\n    -- Abstract method returning table of telemetry data\n    return {\n        status = self.CurrentStatus,\n        isFarming = self.IsFarming\n    }\nend\n\nfunction BaseGame:Cleanup()\n    -- Clean up running loops, hooks, connections\n    self.IsFarming = false\nend\n\nreturn BaseGame\n\nend\n\nModules[\"games/cdid\"] = function()\n--[[\n    OneEight External Hub - Car Driving Indonesia (CDID) Game Module\n    Exact Clone of OneEight In-Game Truck Engine (CDID Farming Truck v1):\n    - Full 4-Phase Tween Truck Engine (Fly 400 studs -> Adaptive Forward -> Sine Out Landing -> Release Trigger)\n    - Waypoint & Destination Dynamic Detection (workspace.Etc.Waypoint & Destination)\n    - Starter & Spawner ProximityPrompt Automation\n    - Automatic Vehicle Seat Claim & ProximityPrompt firing\n    - Disguised Reroll as \"GET_BEST_DESTINATION\"\n    - Controlled 100% via WebSocket from Web Dashboard (Headless)\n--]]\n\nlocal CDIDModule = {}\nCDIDModule.GameId = \"cdid\"\nCDIDModule.GameName = \"Car Driving Indonesia\"\nCDIDModule.CurrencyUnit = \"Rp\"\nCDIDModule.MetricUnit = \"Trips\"\n\nlocal TweenService = game:GetService(\"TweenService\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Workspace = game:GetService(\"Workspace\")\nlocal LocalPlayer = Players.LocalPlayer\n\nlocal Context = nil\n\n-- ============================================================================\n-- 1. CORE ONEEIGHT LOGIC (100% CLONE FROM ONEEIGHT IN-GAME ENGINE)\n-- ============================================================================\nlocal Core = {}\nCore.AutoFarm = false\nCore.FarmSessionID = 0\nCore.CurrentMoney = 0\nCore.EarnedMoney = 0\nCore.AverageEarning = 0\nCore.SessionStartMoney = 0\nCore.SessionStartTime = 0\nCore.LastMoney = 0\nCore.ActiveTweenConnections = {}\nCore.CountdownTime = 0\nCore.TripCount = 0\nCore.LowRender = false\nCore.CurrentRoute = \"IDLE\"\nCore.CurrentStatus = \"READY\"\n\nCore.Settings = {\n    TweenDuration = 41.2,\n    MinDistance = 100000\n}\n\n-- Utilities\nfunction Core.parseMoney(text)\n    if not text then return 0 end\n    local cleanText = string.gsub(tostring(text), \"[^%d]\", \"\")\n    return tonumber(cleanText) or 0\nend\n\nfunction Core.formatRupiah(amount)\n    if not amount then return \"Rp 0\" end\n    local formatted = tostring(math.floor(math.abs(tonumber(amount) or 0)))\n    while true do  \n        local k\n        formatted, k = string.gsub(formatted, \"^(-?%d+)(%d%d%d)\", '%1.%2')\n        if k == 0 then break end\n    end\n    return (tonumber(amount) and tonumber(amount) < 0 and \"-Rp \" or \"Rp \") .. formatted\nend\n\nfunction Core.calculateDistance(posA, posB)\n    if not posA or not posB then return 0 end\n    return (posA - posB).Magnitude\nend\n\n-- Teleport Player Safe\nfunction Core.teleportPlayerSafe(targetCFrame)\n    local character = LocalPlayer.Character\n    if character and character:FindFirstChild(\"HumanoidRootPart\") then\n        local humanoid = character:FindFirstChildOfClass(\"Humanoid\")\n        if humanoid and humanoid.SeatPart then\n            humanoid.Sit = false\n            task.wait(0.1)\n        end\n        character:PivotTo(targetCFrame)\n    end\nend\n\n-- Cleanup Truck Physics\nfunction Core.cleanupTruckPhysics(car, originalStates)\n    if not car then return end\n    for part, states in pairs(originalStates) do\n        if part and part.Parent and part:IsA(\"BasePart\") then \n            pcall(function()\n                part.CanCollide = states.CanCollide\n                part.Anchored = states.Anchored\n            end)\n        end\n    end\nend\n\n-- Waypoint & Destination Logic (OneEight exact functions)\nfunction Core.getClosestWaypoint(referencePos)\n    local wpFolder = Workspace:FindFirstChild(\"Etc\") and Workspace.Etc:FindFirstChild(\"Waypoint\")\n    if wpFolder then\n        local closestWP = nil\n        local shortestDistance = math.huge\n        if not referencePos and LocalPlayer.Character and LocalPlayer.Character.PrimaryPart then\n            referencePos = LocalPlayer.Character.PrimaryPart.Position\n        end\n        for _, wp in ipairs(wpFolder:GetChildren()) do\n            if wp.Name == \"Waypoint\" and wp:IsA(\"BasePart\") then\n                if referencePos then\n                    local dist = (wp.Position - referencePos).Magnitude\n                    if dist < shortestDistance then\n                        shortestDistance = dist\n                        closestWP = wp\n                    end\n                else\n                    return wp\n                end\n            end\n        end\n        return closestWP\n    end\n    return nil\nend\n\nfunction Core.getDestPart(referencePos)\n    local destFolder = Workspace:FindFirstChild(\"Etc\") and Workspace.Etc:FindFirstChild(\"Job\") and Workspace.Etc.Job:FindFirstChild(\"Truck\")\n    if destFolder and destFolder:FindFirstChild(\"Destination\") then\n        local closestPart = nil\n        local shortestDistance = math.huge\n        if not referencePos and LocalPlayer.Character and LocalPlayer.Character.PrimaryPart then\n            referencePos = LocalPlayer.Character.PrimaryPart.Position\n        end\n        for _, part in ipairs(destFolder.Destination:GetChildren()) do\n            if part:IsA(\"BasePart\") then\n                if referencePos then\n                    local dist = (part.Position - referencePos).Magnitude\n                    if dist < shortestDistance then\n                        shortestDistance = dist\n                        closestPart = part\n                    end\n                else\n                    return part\n                end\n            end\n        end\n        return closestPart\n    end\n    return nil\nend\n\n-- UI / Web Sync Callbacks\nCore.UpdateStatusUI = function(text)\n    Core.CurrentStatus = text\n    if Context and Context.SendLog then\n        Context.SendLog(text, \"INFO\")\n    end\nend\n\nCore.StartCountdown = function(duration)\n    Core.CountdownTime = math.floor(duration or 0)\n    task.spawn(function()\n        local endTime = tick() + (duration or 0)\n        while tick() < endTime and Core.AutoFarm do\n            local remaining = math.max(0, math.floor(endTime - tick()))\n            Core.CountdownTime = remaining\n            task.wait(0.5)\n        end\n        Core.CountdownTime = 0\n    end)\nend\n\n-- ============================================================================\n-- MAIN TWEEN LOGIC (ONE-EIGHT 4-PHASE ENGINE)\n-- ============================================================================\nfunction Core.tweenTruckSafe(car, initialTargetPart, totalTweenTime, currentSession)\n    if not car or not car.PrimaryPart or not initialTargetPart then return nil end\n    local startCF = car:GetPivot()\n    local flightHeight = 400\n    local truckOriginalStates = {}\n\n    for _, part in ipairs(car:GetDescendants()) do\n        if part:IsA(\"BasePart\") then\n            truckOriginalStates[part] = { CanCollide = part.CanCollide, Anchored = part.Anchored }\n            pcall(function() part.Anchored = true end)\n        end\n    end\n\n    local proxyValue = Instance.new(\"CFrameValue\")\n    proxyValue.Value = startCF\n    \n    local connNoClip = RunService.Stepped:Connect(function()\n        for _, part in ipairs(car:GetDescendants()) do\n            if part:IsA(\"BasePart\") then part.CanCollide = false end\n        end\n        if LocalPlayer.Character then\n            for _, part in ipairs(LocalPlayer.Character:GetDescendants()) do\n                if part:IsA(\"BasePart\") then part.CanCollide = false end\n            end\n        end\n    end)\n    \n    local connProxy = RunService.Heartbeat:Connect(function()\n        car:PivotTo(proxyValue.Value)\n    end)\n    table.insert(Core.ActiveTweenConnections, connNoClip)\n    table.insert(Core.ActiveTweenConnections, connProxy)\n\n    local function abortTweenAndCleanup()\n        connNoClip:Disconnect()\n        connProxy:Disconnect()\n        proxyValue:Destroy()\n        Core.cleanupTruckPhysics(car, truckOriginalStates)\n    end\n\n    local currentTarget = initialTargetPart\n    local isTrackingDest = false\n\n    -- FASE 1: NAIK\n    Core.UpdateStatusUI(\"Flying Up...\")\n    Core.StartCountdown(3)\n    local upAirCF = startCF + Vector3.new(0, flightHeight, 0)\n    local tweenUp = TweenService:Create(proxyValue, TweenInfo.new(3, Enum.EasingStyle.Linear), {Value = upAirCF})\n    tweenUp:Play() \n    while tweenUp.PlaybackState == Enum.PlaybackState.Playing do\n        if not Core.AutoFarm or Core.FarmSessionID ~= currentSession then\n            tweenUp:Cancel()\n            abortTweenAndCleanup()\n            return\n        end\n        task.wait(0.1)\n    end\n\n    -- FASE 2: MAJU \n    local initialTargetAirCF = CFrame.new(currentTarget.Position.X, upAirCF.Position.Y, currentTarget.Position.Z) * startCF.Rotation\n    local totalDistance = math.max(1, (upAirCF.Position - initialTargetAirCF.Position).Magnitude)\n    local adaptiveSpeed = totalDistance / (totalTweenTime or 41.2)\n\n    local function startForwardTween(targetAirCF)\n        local distance = (proxyValue.Value.Position - targetAirCF.Position).Magnitude\n        local tTime = math.max(0.5, distance / adaptiveSpeed)\n        Core.UpdateStatusUI(string.format(\"DRIVING (%ds)\", math.ceil(tTime)))\n        Core.StartCountdown(tTime)\n        local fwd = TweenService:Create(proxyValue, TweenInfo.new(tTime, Enum.EasingStyle.Linear), {Value = targetAirCF})\n        fwd:Play()\n        return fwd\n    end\n\n    local currentFwdTween = startForwardTween(initialTargetAirCF)\n\n    while currentFwdTween.PlaybackState == Enum.PlaybackState.Playing do\n        if not Core.AutoFarm or Core.FarmSessionID ~= currentSession then\n            currentFwdTween:Cancel()\n            abortTweenAndCleanup()\n            return\n        end\n\n        if not isTrackingDest then\n            if (proxyValue.Value.Position - currentTarget.Position).Magnitude < 200 then\n                local destPart = Core.getDestPart(proxyValue.Value.Position)\n                if destPart then\n                    currentFwdTween:Cancel()\n                    currentTarget = destPart\n                    isTrackingDest = true\n                    Core.UpdateStatusUI(\"Destination Found! Retargeting...\")\n                    task.wait(0.1)\n                    local newTargetAirCF = CFrame.new(currentTarget.Position.X, upAirCF.Position.Y, currentTarget.Position.Z) * startCF.Rotation\n                    currentFwdTween = startForwardTween(newTargetAirCF)\n                end\n            end\n        end\n        task.wait(0.2)\n    end\n\n    -- FASE 3: TURUN\n    Core.UpdateStatusUI(\"Landing...\")\n    Core.StartCountdown(4)\n    local targetGroundCF = currentTarget.CFrame * CFrame.new(0, (car:GetExtentsSize().Y / 2) - 4.5, 0)\n    local tweenDown = TweenService:Create(proxyValue, TweenInfo.new(4, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {Value = targetGroundCF})\n    tweenDown:Play() \n    while tweenDown.PlaybackState == Enum.PlaybackState.Playing do\n        if not Core.AutoFarm or Core.FarmSessionID ~= currentSession then\n            tweenDown:Cancel()\n            abortTweenAndCleanup()\n            return\n        end\n        task.wait(0.1)\n    end\n\n    -- FASE 4: CLEANUP & TOUCH TRIGGER\n    abortTweenAndCleanup()\n    if car.PrimaryPart and Core.AutoFarm and Core.FarmSessionID == currentSession then\n        Core.UpdateStatusUI(\"Releasing & Triggering...\")\n        task.wait(0.5)\n        for i = 1, 3 do\n            if not Core.AutoFarm or Core.FarmSessionID ~= currentSession then break end\n            car:PivotTo(car:GetPivot() * CFrame.new(0, -0.3, 0))\n            task.wait(0.2)\n            car:PivotTo(car:GetPivot() * CFrame.new(0, 0.3, 0))\n            task.wait(0.2)\n        end\n    end\n    return currentTarget\nend\n\n-- ============================================================================\n-- AUTOFARM LOOP (ONE-EIGHT CLONE WITH DISGUISED REROLL)\n-- ============================================================================\nfunction Core.StartFarmLoop(sessionID)\n    task.spawn(function()\n        while Core.AutoFarm and Core.FarmSessionID == sessionID do\n            local character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()\n            local humanoid = character:WaitForChild(\"Humanoid\", 10)\n            if not humanoid then continue end\n\n            Core.UpdateStatusUI(\"Taking Job...\")\n            pcall(function()\n                ReplicatedStorage:WaitForChild(\"NetworkContainer\"):WaitForChild(\"RemoteEvents\"):WaitForChild(\"Job\"):FireServer(\"Truck\")\n            end)\n            task.wait(1)\n            if not Core.AutoFarm or Core.FarmSessionID ~= sessionID then break end\n\n            Core.UpdateStatusUI(\"Interacting Starter...\")\n            local starterFolder = Workspace:FindFirstChild(\"Etc\") and Workspace.Etc:FindFirstChild(\"Job\") and Workspace.Etc.Job:FindFirstChild(\"Truck\") and Workspace.Etc.Job.Truck:FindFirstChild(\"Starter\")\n            if starterFolder then\n                local starterPrompt = starterFolder:FindFirstChildWhichIsA(\"ProximityPrompt\", true)\n                if starterPrompt and starterPrompt.Parent then\n                    starterPrompt.RequiresLineOfSight = false\n                    starterPrompt.MaxActivationDistance = 50\n                    Core.teleportPlayerSafe(starterPrompt.Parent:GetPivot() * CFrame.new(0, 5, 0))\n                    task.wait(0.5)\n                    if fireproximityprompt then\n                        pcall(fireproximityprompt, starterPrompt)\n                    else\n                        starterPrompt:InputHoldBegin()\n                        task.wait(0.2)\n                        starterPrompt:InputHoldEnd()\n                    end\n                    task.wait(1.5)\n                    if fireproximityprompt then\n                        pcall(fireproximityprompt, starterPrompt)\n                    else\n                        starterPrompt:InputHoldBegin()\n                        task.wait(0.2)\n                        starterPrompt:InputHoldEnd()\n                    end\n                end\n            end\n            if not Core.AutoFarm or Core.FarmSessionID ~= sessionID then break end\n\n            -- Hitung Jarak & Seleksi Rute Terbaik (Disguised Reroll)\n            local rootPart = character.PrimaryPart or character:FindFirstChild(\"HumanoidRootPart\")\n            task.wait(0.5) \n            local initialTarget = Core.getClosestWaypoint(rootPart and rootPart.Position) or Core.getDestPart(rootPart and rootPart.Position)\n            if not initialTarget then\n                task.wait(0.5)\n                initialTarget = Core.getClosestWaypoint(rootPart and rootPart.Position) or Core.getDestPart(rootPart and rootPart.Position)\n            end\n\n            if initialTarget and rootPart then\n                local initialDistance = Core.calculateDistance(rootPart.Position, initialTarget.Position)\n                if initialDistance < Core.Settings.MinDistance then\n                    -- Samarkan Reroll sebagai \"GET_BEST_DESTINATION\"\n                    Core.CurrentStatus = \"GET_BEST_DESTINATION\"\n                    if Context and Context.SendLog then\n                        Context.SendLog(\"Menganalisis rute terbaik...\", \"INFO\")\n                    end\n                    pcall(function()\n                        ReplicatedStorage:WaitForChild(\"NetworkContainer\"):WaitForChild(\"RemoteEvents\"):WaitForChild(\"Job\"):FireServer(\"Cancel\")\n                    end)\n                    task.wait(1)\n                    continue \n                end\n            end\n            if not Core.AutoFarm or Core.FarmSessionID ~= sessionID then break end\n\n            -- Set Clean Route Name (Tanpa Tanda Kurung)\n            local targetName = (initialTarget and initialTarget.Name ~= \"Waypoint\" and initialTarget.Name) or \"PT CDID Cargo\"\n            Core.CurrentRoute = targetName\n            if Context and Context.SendLog then\n                Context.SendLog(string.format(\"Rute Terbaik: %s! Memunculkan truk...\", targetName), \"SUCCESS\")\n            end\n\n            Core.UpdateStatusUI(\"Spawning Truck...\")\n            local spawnerFolder = Workspace:FindFirstChild(\"Etc\") and Workspace.Etc:FindFirstChild(\"Job\") and Workspace.Etc.Job:FindFirstChild(\"Truck\") and Workspace.Etc.Job.Truck:FindFirstChild(\"Spawner\")\n            if spawnerFolder then\n                local spawnerPrompt = spawnerFolder:FindFirstChildWhichIsA(\"ProximityPrompt\", true)\n                if spawnerPrompt and spawnerPrompt.Parent then\n                    spawnerPrompt.RequiresLineOfSight = false\n                    spawnerPrompt.MaxActivationDistance = 50\n                    Core.teleportPlayerSafe(spawnerPrompt.Parent:GetPivot() * CFrame.new(0, 5, 0))\n                    task.wait(1)\n                    if fireproximityprompt then\n                        pcall(fireproximityprompt, spawnerPrompt)\n                    else\n                        spawnerPrompt:InputHoldBegin()\n                        task.wait(0.2)\n                        spawnerPrompt:InputHoldEnd()\n                    end\n                    task.wait(1)\n                end\n            end\n            if not Core.AutoFarm or Core.FarmSessionID ~= sessionID then break end\n\n            Core.UpdateStatusUI(\"Entering Truck...\")\n            local truckName = LocalPlayer.Name .. \"sCar\" \n            local truck = Workspace:WaitForChild(\"Vehicles\", 10) and Workspace.Vehicles:WaitForChild(truckName, 10)\n            local driveSeat = truck and truck:WaitForChild(\"DriveSeat\", 5)\n\n            if driveSeat then\n                local drivePrompt = driveSeat:FindFirstChildWhichIsA(\"ProximityPrompt\", true)\n                if drivePrompt then\n                    drivePrompt.RequiresLineOfSight = false\n                    drivePrompt.MaxActivationDistance = 50\n                    Core.teleportPlayerSafe(driveSeat:GetPivot() * CFrame.new(0, 5, 0))\n                    task.wait(1)\n                    if fireproximityprompt then\n                        pcall(fireproximityprompt, drivePrompt)\n                    else\n                        drivePrompt:InputHoldBegin()\n                        task.wait(0.2)\n                        drivePrompt:InputHoldEnd()\n                    end\n                    task.wait(0.3)\n                end\n            end\n            if not Core.AutoFarm or Core.FarmSessionID ~= sessionID then break end\n\n            if driveSeat and (driveSeat.Occupant ~= nil or humanoid.Sit == true) then\n                local jobCancelled = false\n                while Core.AutoFarm and Core.FarmSessionID == sessionID and (driveSeat.Occupant ~= nil or humanoid.Sit == true) do\n                    local truckPos = truck.PrimaryPart and truck.PrimaryPart.Position\n                    local currentTarget = Core.getClosestWaypoint(truckPos) or Core.getDestPart(truckPos)\n                    if not currentTarget then\n                        task.wait(1)\n                        currentTarget = Core.getClosestWaypoint(truckPos) or Core.getDestPart(truckPos)\n                    end\n\n                    if currentTarget then\n                        local currentDistance = Core.calculateDistance(truckPos, currentTarget.Position)\n                        if currentDistance < Core.Settings.MinDistance then\n                            Core.CurrentStatus = \"GET_BEST_DESTINATION\"\n                            if Context and Context.SendLog then\n                                Context.SendLog(\"Menganalisis rute terbaik...\", \"INFO\")\n                            end\n                            pcall(function()\n                                ReplicatedStorage:WaitForChild(\"NetworkContainer\"):WaitForChild(\"RemoteEvents\"):WaitForChild(\"Job\"):FireServer(\"Cancel\")\n                            end)\n                            if humanoid then humanoid.Sit = false end\n                            jobCancelled = true\n                            task.wait(1.2)\n                            break \n                        end\n\n                        local finalPartReached = Core.tweenTruckSafe(truck, currentTarget, Core.Settings.TweenDuration, sessionID)\n                        local isDestination = finalPartReached and finalPartReached.Parent and finalPartReached.Parent.Name == \"Destination\"\n                        if isDestination then\n                            Core.TripCount = Core.TripCount + 1\n                            if Context and Context.SendLog then\n                                Context.SendLog(string.format(\"Pengiriman #%d Selesai! Menunggu pembayaran...\", Core.TripCount), \"SUCCESS\")\n                            end\n                            Core.UpdateStatusUI(\"Reached Destination! Waiting 3s...\")\n                            task.wait(3)\n                        else\n                            local waitTimeout, originalPos = 0, currentTarget.Position\n                            while currentTarget and currentTarget.Parent and (currentTarget.Position - originalPos).Magnitude < 2 and waitTimeout < 5 do\n                                task.wait(0.5)\n                                waitTimeout = waitTimeout + 0.5\n                            end\n                        end\n                    else\n                        break\n                    end\n                end\n\n                if Core.AutoFarm and Core.FarmSessionID == sessionID and not jobCancelled then\n                    Core.UpdateStatusUI(\"Job Complete!\")\n                    task.wait(2)\n                end\n            end\n        end\n    end)\nend\n\nfunction Core.ToggleFarm(state)\n    Core.AutoFarm = state\n    Core.FarmSessionID = Core.FarmSessionID + 1 \n    \n    if Core.AutoFarm then\n        local playerGui = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        local moneyLabel = playerGui and playerGui:FindFirstChild(\"Main\") and \n                           playerGui.Main:FindFirstChild(\"Container\") and \n                           playerGui.Main.Container:FindFirstChild(\"Hub\") and \n                           playerGui.Main.Container.Hub:FindFirstChild(\"CashFrame\") and \n                           playerGui.Main.Container.Hub.CashFrame:FindFirstChild(\"Frame\") and \n                           playerGui.Main.Container.Hub.CashFrame.Frame:FindFirstChild(\"TextLabel\")\n                           \n        if moneyLabel and moneyLabel.Text then\n            Core.SessionStartMoney = Core.parseMoney(moneyLabel.Text)\n            Core.LastMoney = Core.SessionStartMoney \n            Core.CurrentMoney = Core.SessionStartMoney\n        end\n        Core.SessionStartTime = tick()\n        Core.CurrentStatus = \"STARTING\"\n        if Context and Context.SendLog then\n            Context.SendLog(\"Memulai OneEight Truck Auto Farm (Tween Mode)\", \"SUCCESS\")\n        end\n        Core.StartFarmLoop(Core.FarmSessionID)\n    else\n        Core.CurrentStatus = \"STOPPED\"\n        Core.CurrentRoute = \"IDLE\"\n        Core.CountdownTime = 0\n        if Context and Context.SendLog then\n            Context.SendLog(\"Menghentikan OneEight Auto Farm...\", \"WARN\")\n        end\n        for _, conn in ipairs(Core.ActiveTweenConnections) do\n            pcall(function() conn:Disconnect() end)\n        end\n        table.clear(Core.ActiveTweenConnections)\n    end\nend\n\n-- Tracker Saldo Real-Time\ntask.spawn(function()\n    while true do\n        task.wait(1)\n        local playerGui = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        local moneyLabel = playerGui and playerGui:FindFirstChild(\"Main\") and \n                           playerGui.Main:FindFirstChild(\"Container\") and \n                           playerGui.Main.Container:FindFirstChild(\"Hub\") and \n                           playerGui.Main.Container.Hub:FindFirstChild(\"CashFrame\") and \n                           playerGui.Main.Container.Hub.CashFrame:FindFirstChild(\"Frame\") and \n                           playerGui.Main.Container.Hub.CashFrame.Frame:FindFirstChild(\"TextLabel\")\n\n        if moneyLabel and moneyLabel.Text then\n            Core.CurrentMoney = Core.parseMoney(moneyLabel.Text)\n            \n            if Core.AutoFarm then\n                if Core.SessionStartMoney == 0 then\n                    Core.SessionStartMoney = Core.CurrentMoney\n                    Core.LastMoney = Core.CurrentMoney\n                end\n                if Core.CurrentMoney ~= Core.LastMoney then\n                    Core.EarnedMoney = Core.CurrentMoney - Core.SessionStartMoney\n                    local runningHours = (tick() - Core.SessionStartTime) / 3600\n                    if runningHours > 0 then\n                        Core.AverageEarning = math.floor(Core.EarnedMoney / runningHours)\n                    end\n                    Core.LastMoney = Core.CurrentMoney\n                end\n            else\n                Core.LastMoney = Core.CurrentMoney\n            end\n        end\n    end\nend)\n\n-- ============================================================================\n-- INTERFACE CONTRACT IMPLEMENTATION FOR EXTERNAL WEB CONTROL\n-- ============================================================================\nfunction CDIDModule.Init(coreContext)\n    Context = coreContext\n    print(\"[OE-External CDID] Modul OneEight Truck Engine resmi dimuat & terhubung ke Web!\")\nend\n\nfunction CDIDModule.HandleCommand(action, payload)\n    if action == \"START_FARM\" then\n        if not Core.AutoFarm then\n            Core.ToggleFarm(true)\n        end\n        return true\n\n    elseif action == \"STOP_FARM\" then\n        if Core.AutoFarm then\n            Core.ToggleFarm(false)\n        end\n        return true\n\n    elseif action == \"TOGGLE_LOW_RENDER\" then\n        Core.LowRender = not Core.LowRender\n        pcall(function()\n            if typeof(RunService.Set3dRenderingEnabled) == \"function\" then\n                RunService:Set3dRenderingEnabled(not Core.LowRender)\n            end\n        end)\n        if Context and Context.SendLog then\n            Context.SendLog(\"Low GPU Mode: \" .. (Core.LowRender and \"AKTIF (3D Off)\" or \"NONAKTIF (3D On)\"), \"INFO\")\n        end\n        return true\n\n    elseif action == \"TELEPORT_HQ\" then\n        if Context and Context.SendLog then\n            Context.SendLog(\"Teleportasi manual ke Depo HQ...\", \"INFO\")\n        end\n        Core.teleportPlayerSafe(CFrame.new(34938, 138, -54578))\n        return true\n\n    elseif action == \"SET_MIN_DISTANCE\" then\n        if payload and payload.minDistance then\n            Core.Settings.MinDistance = tonumber(payload.minDistance) or 100000\n            if Context and Context.SendLog then\n                Context.SendLog(\"Konfigurasi Best Destination diperbarui: \" .. tostring(Core.Settings.MinDistance), \"INFO\")\n            end\n        end\n        return true\n    end\n\n    return false\nend\n\nfunction CDIDModule.GetTelemetry()\n    local elapsedSec = (Core.AutoFarm and Core.SessionStartTime > 0) and math.floor(tick() - Core.SessionStartTime) or 0\n    return {\n        status = Core.CurrentStatus,\n        currentRoute = Core.CurrentRoute,\n        tripCount = Core.TripCount,\n        totalEarnings = Core.EarnedMoney,\n        currentCash = Core.CurrentMoney,\n        startCash = Core.SessionStartMoney,\n        isFarming = Core.AutoFarm,\n        lowRender = Core.LowRender,\n        minDistance = Core.Settings.MinDistance,\n        farmDuration = elapsedSec\n    }\nend\n\nfunction CDIDModule.Cleanup()\n    Core.ToggleFarm(false)\nend\n\nreturn CDIDModule\n\nend\n\nModules[\"games/cdid_menu\"] = function()\n--[[\n    OneEight External Hub - CDID Main Menu & Server Gateway Module\n    100% Exact Port of OneEight Hub Server Manager:\n    - Realtime multi-source private server code detection (UI, GC Replica, NetworkEvent)\n    - Free private server code generation (Network:FireServer(\"PrivateServer\", \"Create\"))\n    - Native map selection & controller synchronization (UIAnimation.SelectedMap)\n    - Full bidirectional server code sync with Web Dashboard\n    - Auto-Enter Jawa Timur with auto-code fallback & queue_on_teleport\n--]]\n\nlocal CDIDMenu = {}\nCDIDMenu.GameId = \"cdid_menu\"\nCDIDMenu.GameName = \"CDID Main Menu\"\nCDIDMenu.CurrencyUnit = \"Rp\"\nCDIDMenu.MetricUnit = \"Maps\"\n\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal TeleportService = game:GetService(\"TeleportService\")\nlocal LocalPlayer = Players.LocalPlayer\n\nlocal Context = nil\nlocal State = {\n    Status = \"LOBBY_READY\",\n    AutoJoinJatim = false,\n    CurrentServerCode = \"\",\n    SelectedMap = \"JawaTimur\",\n    AutoJoinTimer = 5,\n    CodeSource = \"None\"\n}\n\nlocal CDID_MAPS = {\n    { Key = \"JawaTimur\",   Name = \"Jawa Timur\",   PlaceId = 110369730911937, Desc = \"Pusat Truck Cargo Auto Farm\", Icon = \"truck\", Primary = true },\n    { Key = \"Jakarta\",     Name = \"Jakarta\",      PlaceId = 14005966837,     Desc = \"Kurir BCA & Cafe Kanji Jawa\",  Icon = \"building\" },\n    { Key = \"Bandung\",     Name = \"Bandung\",      PlaceId = 79488788685813,  Desc = \"Kota Kembang\",                Icon = \"compass\" },\n    { Key = \"JawaBarat\",   Name = \"Jawa Barat\",   PlaceId = 9233343468,      Desc = \"Tol & Pegunungan\",            Icon = \"compass\" },\n    { Key = \"JawaTengah\",  Name = \"Jawa Tengah\",  PlaceId = 9508940498,      Desc = \"Semarang & Solo\",             Icon = \"compass\" },\n    { Key = \"Bali\",        Name = \"Bali\",         PlaceId = 118108582994420, Desc = \"Pulau Dewata\",               Icon = \"palm-tree\" },\n    { Key = \"Seasonal\",    Name = \"Seasonal\",     PlaceId = 132986577553100, Desc = \"Event Khusus\",               Icon = \"sparkles\" }\n}\n\n-- Native CDID Network Helper\nlocal CDID_Network = nil\nlocal CDID_UIAnimation = nil\n\nlocal function getCDIDNetwork()\n    if CDID_Network then return CDID_Network end\n    pcall(function()\n        local shared = ReplicatedStorage:FindFirstChild(\"Shared\")\n        if shared and shared:FindFirstChild(\"Network\") then\n            CDID_Network = require(shared.Network)\n        end\n    end)\n    return CDID_Network\nend\n\nlocal function getRealUIAnimation()\n    local success, result = pcall(function()\n        for _, v in ipairs(getgc(true)) do\n            if type(v) == \"table\" and rawget(v, \"SelectedMap\") and rawget(v, \"WindowModule\") then\n                return v\n            end\n        end\n    end)\n    return success and result or nil\nend\n\n-- ============================================================================\n-- VALIDASI & PENERAPAN KODE SERVER (ONE-EIGHT HUB ALGORITHM)\n-- ============================================================================\nlocal function isValidServerCode(text)\n    if not text or type(text) ~= \"string\" then return false end\n    local clean = text:gsub(\"%s+\", \"\")\n    if clean == \"\" or clean == \"ServerLabel\" or clean == \"nil\" or clean == \"InsertHere\" then return false end\n    local lower = clean:lower()\n    if lower:find(\"ms\") or lower:find(\"fps\") or lower:find(\"singapore\")\n        or lower:find(\"unitedstates\") or lower:find(\"indonesia\") or lower:find(\",\") then\n        return false\n    end\n    return (clean:len() >= 4 and clean:len() <= 35)\nend\n\nlocal function applyServerCode(code, source)\n    if not isValidServerCode(code) then return false end\n    local clean = tostring(code):gsub(\"%s+\", \"\")\n    if clean == State.CurrentServerCode then return false end\n\n    State.CurrentServerCode = clean\n    State.CodeSource = source or \"Unknown\"\n    print(string.format(\"[OE-External CDID] 🔑 Kode Server Terdeteksi [%s]: %s\", State.CodeSource, State.CurrentServerCode))\n\n    if Context and Context.SendLog then\n        Context.SendLog(string.format(\"Kode Server CDID terdeteksi (%s): %s\", State.CodeSource, State.CurrentServerCode), \"SUCCESS\")\n    end\n\n    -- Update ke GUI CDID jika ada\n    pcall(function()\n        local pGui = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        local ps = pGui and pGui:FindFirstChild(\"Hub\") and pGui.Hub.Container.Window:FindFirstChild(\"PrivateServer\")\n        if ps and ps:FindFirstChild(\"ServerLabel\") then\n            ps.ServerLabel.Text = State.CurrentServerCode\n        end\n    end)\n\n    return true\nend\n\n-- ============================================================================\n-- MULTI-SOURCE SCANNER (EXACT ONE-EIGHT HUB METHOD)\n-- ============================================================================\nlocal function scanAllSources()\n    -- Sumber 1: Real UIAnimation dari GC\n    local realUI = getRealUIAnimation()\n    if realUI and realUI.WindowModule then\n        local ps = realUI.WindowModule.PrivateServer\n        if ps and ps.ServerLabel and isValidServerCode(ps.ServerLabel.Text) then\n            return applyServerCode(ps.ServerLabel.Text, \"UIAnimation\")\n        end\n    end\n\n    -- Sumber 2: Recursive scan di PlayerGui untuk ServerLabel\n    local pGui = LocalPlayer:FindFirstChild(\"PlayerGui\")\n    if pGui then\n        for _, inst in ipairs(pGui:GetDescendants()) do\n            if (inst:IsA(\"TextLabel\") or inst:IsA(\"TextBox\")) and inst.Name == \"ServerLabel\" then\n                if isValidServerCode(inst.Text) then\n                    return applyServerCode(inst.Text, \"PlayerGui.ServerLabel\")\n                end\n            end\n        end\n    end\n\n    -- Sumber 3: ReplicaService Player Data State (GC scan)\n    local replicaCode = nil\n    pcall(function()\n        for _, v in ipairs(getgc(true)) do\n            if type(v) == \"table\" and type(rawget(v, \"Class\")) == \"string\" and rawget(v, \"Class\"):find(\"^Player_\") and rawget(v, \"Data\") then\n                local data = rawget(v, \"Data\")\n                if data and data.PrivateServer and data.PrivateServer.Code and isValidServerCode(data.PrivateServer.Code) then\n                    replicaCode = data.PrivateServer.Code\n                    break\n                end\n            end\n        end\n    end)\n    if replicaCode then\n        return applyServerCode(replicaCode, \"GCReplicaScan\")\n    end\n\n    return false\nend\n\n-- Request kode baru dari server game CDID\nlocal function requestServerCode()\n    print(\"[OE-External CDID] 🔄 Meminta pembuatan kode server private baru...\")\n    if Context and Context.SendLog then\n        Context.SendLog(\"Meminta server CDID untuk generate kode private baru...\", \"INFO\")\n    end\n\n    local net = getCDIDNetwork()\n    if net and net.FireServer then\n        pcall(function()\n            net:FireServer(\"PrivateServer\", \"Create\")\n        end)\n    end\n\n    -- Polling agresif selama 5 detik\n    for _ = 1, 15 do\n        task.wait(0.3)\n        if scanAllSources() then\n            return State.CurrentServerCode\n        end\n    end\n    return State.CurrentServerCode\nend\n\n-- ============================================================================\n-- MAP SELECTION & JOIN DISPATCHER\n-- ============================================================================\nlocal function selectMapNative(mapKey)\n    State.SelectedMap = mapKey\n\n    -- 1. Sync ke real UIAnimation di GC\n    local realUI = getRealUIAnimation()\n    if realUI then\n        pcall(function() realUI.SelectedMap = mapKey end)\n    end\n\n    -- 2. Sync ke Controller UIAnimation CDID\n    pcall(function()\n        local controller = ReplicatedStorage:FindFirstChild(\"Controller\")\n        if controller and controller:FindFirstChild(\"UIAnimation\") then\n            local uiMod = require(controller.UIAnimation)\n            if uiMod then uiMod.SelectedMap = mapKey end\n        end\n    end)\n\n    -- 3. Trigger tombol map di PlayerGui.Hub\n    pcall(function()\n        local mapWin = LocalPlayer.PlayerGui.Hub.Container.Window:FindFirstChild(\"MapSelection\")\n        local targetMapFrame = mapWin and mapWin:FindFirstChild(mapKey)\n        local btn = targetMapFrame and targetMapFrame:FindFirstChild(\"TextButton\")\n        if btn then\n            local conns = getconnections and getconnections(btn.MouseButton1Down) or {}\n            for _, c in ipairs(conns) do\n                if c.Function then pcall(c.Function) end\n            end\n            if typeof(firesignal) == \"function\" then\n                pcall(firesignal, btn.MouseButton1Down)\n            end\n        end\n    end)\nend\n\nlocal function joinMap(mapKey, serverCode)\n    mapKey = mapKey or State.SelectedMap or \"JawaTimur\"\n    State.Status = \"JOINING_\" .. string.upper(mapKey)\n\n    -- Setup queue_on_teleport agar loader kembali berjalan di server tujuan\n    local queue_teleport = (syn and syn.queue_on_teleport) or queue_on_teleport or (fluxus and fluxus.queue_on_teleport)\n    if queue_teleport then\n        pcall(function()\n            queue_teleport([[\n                task.wait(4)\n                loadstring(game:HttpGet(\"https://externalhub.oneeight-project18.workers.dev/loader\"))()\n            ]])\n        end)\n    end\n\n    -- 1. Pastikan Kode Server Terisi\n    local codeToUse = serverCode\n    if not codeToUse or codeToUse == \"\" then\n        codeToUse = State.CurrentServerCode\n    end\n\n    if not codeToUse or codeToUse == \"\" then\n        scanAllSources()\n        codeToUse = State.CurrentServerCode\n    end\n\n    -- Jika masih belum ada, minta server buatkan kode otomatis sekarang juga\n    if not codeToUse or codeToUse == \"\" then\n        codeToUse = requestServerCode()\n    end\n\n    print(string.format(\"[OE-External CDID] 🚀 Melakukan Join ke %s dengan Kode: '%s'...\", mapKey, tostring(codeToUse)))\n    if Context and Context.SendLog then\n        Context.SendLog(string.format(\"Menghubungkan ke %s (Kode: %s)...\", mapKey, tostring(codeToUse)), \"WARN\")\n    end\n\n    selectMapNative(mapKey)\n    task.wait(0.3)\n\n    -- Tutup websocket lama secara bersih agar tidak ada duplikat di backend\n    if _G.OE_ExternalSocket then\n        pcall(function() _G.OE_ExternalSocket:Close() end)\n    end\n\n    -- Pemicu 1: Remote CDID Network (Utama - Persis OneEight Hub)\n    local net = getCDIDNetwork()\n    if net and net.FireServer and codeToUse and codeToUse ~= \"\" then\n        pcall(function()\n            net:FireServer(\"PrivateServer\", \"Join\", tostring(codeToUse), mapKey)\n        end)\n    end\n\n    -- Pemicu 2: Klik tombol Join bawaan UI CDID\n    pcall(function()\n        local ps = LocalPlayer.PlayerGui.Hub.Container.Window.PrivateServer\n        if ps and ps:FindFirstChild(\"ServerLabel\") and codeToUse and #codeToUse > 0 then\n            ps.ServerLabel.Text = tostring(codeToUse)\n        end\n\n        local joinBtn = ps and ps:FindFirstChild(\"JoinButton\") and ps.JoinButton:FindFirstChild(\"TextButton\")\n        if joinBtn then\n            local conns = getconnections and getconnections(joinBtn.MouseButton1Down) or {}\n            for _, c in ipairs(conns) do\n                if c.Function then pcall(c.Function) end\n            end\n            if typeof(firesignal) == \"function\" then\n                pcall(firesignal, joinBtn.MouseButton1Down)\n            end\n        end\n    end)\n\n    -- Pemicu 3: TeleportService Fallback (Jika server code gagal atau join public)\n    task.wait(2.0)\n    local targetPlaceId = nil\n    for _, m in ipairs(CDID_MAPS) do\n        if m.Key == mapKey then\n            targetPlaceId = m.PlaceId\n            break\n        end\n    end\n    if targetPlaceId then\n        pcall(function()\n            TeleportService:Teleport(targetPlaceId, LocalPlayer)\n        end)\n    end\nend\n\n-- ============================================================================\n-- MODUL INIT & BACKGROUND LISTENERS\n-- ============================================================================\nfunction CDIDMenu.Init(coreContext)\n    Context = coreContext\n    print(\"[OE-External CDID] Modul Main Menu / Lobby CDID aktif!\")\n\n    -- Initial scan kode server\n    scanAllSources()\n\n    -- Hook Remote Network jika sudah siap\n    task.spawn(function()\n        local net = getCDIDNetwork()\n        if net and net.OnClientEvent then\n            pcall(function()\n                net.OnClientEvent(\"PrivateServer\", function(action, arg1)\n                    if isValidServerCode(arg1) then\n                        applyServerCode(arg1, \"NetworkEvent\")\n                    elseif isValidServerCode(action) then\n                        applyServerCode(action, \"NetworkEvent\")\n                    end\n                end)\n            end)\n        end\n    end)\n\n    -- Realtime Hook pada PlayerGui ServerLabel\n    task.spawn(function()\n        local pGui = LocalPlayer:WaitForChild(\"PlayerGui\", 10)\n        if not pGui then return end\n\n        local function checkInst(inst)\n            if (inst:IsA(\"TextLabel\") or inst:IsA(\"TextBox\")) and inst.Name == \"ServerLabel\" then\n                if isValidServerCode(inst.Text) then\n                    applyServerCode(inst.Text, \"ServerLabelHook\")\n                end\n                inst:GetPropertyChangedSignal(\"Text\"):Connect(function()\n                    if isValidServerCode(inst.Text) then\n                        applyServerCode(inst.Text, \"ServerLabelChange\")\n                    end\n                end)\n            end\n        end\n\n        for _, inst in ipairs(pGui:GetDescendants()) do checkInst(inst) end\n        pGui.DescendantAdded:Connect(checkInst)\n    end)\n\n    -- Background scanner berkala tiap 3 detik\n    task.spawn(function()\n        while _G.OE_ExternalRunning do\n            task.wait(3)\n            if State.CurrentServerCode == \"\" then\n                scanAllSources()\n            end\n        end\n    end)\n\n    -- Auto-Enter Jawa Timur dinonaktifkan (User memegang kendali penuh)\n    -- Bot tetap standby di lobi dan memindai kode server secara damai\n    task.spawn(function()\n        task.wait(1.5)\n        if State.CurrentServerCode == \"\" then\n            scanAllSources()\n        end\n    end)\nend\n\nfunction CDIDMenu.HandleCommand(action, payload)\n    if action == \"JOIN_MAP\" then\n        local mapKey = payload and payload.mapKey or \"JawaTimur\"\n        local code = payload and payload.code or State.CurrentServerCode\n        joinMap(mapKey, code)\n        return true\n\n    elseif action == \"GENERATE_SERVER_CODE\" then\n        task.spawn(function()\n            requestServerCode()\n        end)\n        return true\n\n    elseif action == \"SET_SERVER_CODE\" then\n        if payload and payload.code then\n            applyServerCode(payload.code, \"WebInput\")\n        end\n        return true\n\n    elseif action == \"TOGGLE_AUTO_JOIN_JATIM\" then\n        State.AutoJoinJatim = not State.AutoJoinJatim\n        if Context and Context.SendLog then\n            Context.SendLog(\"Auto-Enter Jawa Timur: \" .. (State.AutoJoinJatim and \"AKTIF\" or \"NONAKTIF\"), \"INFO\")\n        end\n        return true\n    end\n    return false\nend\n\nfunction CDIDMenu.GetTelemetry()\n    return {\n        status = State.Status,\n        isLobby = true,\n        autoJoinJatim = State.AutoJoinJatim,\n        selectedMap = State.SelectedMap,\n        serverCode = State.CurrentServerCode,\n        codeSource = State.CodeSource,\n        currentRoute = \"Di Lobi (Kode: \" .. (State.CurrentServerCode ~= \"\" and State.CurrentServerCode or \"Belum Ada\") .. \")\",\n        tripCount = 0,\n        totalEarnings = 0,\n        currentCash = 0\n    }\nend\n\nfunction CDIDMenu.Cleanup()\n    State.AutoJoinJatim = false\nend\n\nreturn CDIDMenu\n\nend\n\nModules[\"games/dds\"] = function()\n--[[\n    OneEight External Hub - Drag Drive Simulator (DDS) Game Module\n    Placeholder & Template for Drag Race, Taxi & Barista farming in DDS\n--]]\n\nlocal DDSModule = {}\nDDSModule.GameId = \"dds\"\nDDSModule.GameName = \"Drag Drive Simulator\"\nDDSModule.CurrencyUnit = \"Coins\"\nDDSModule.MetricUnit = \"Races\"\n\nlocal Context = nil\nlocal State = {\n    IsFarming = false,\n    Status = \"STANDBY\",\n    RaceCount = 0,\n    TotalEarnings = 0,\n    CurrentCoins = 0,\n    CurrentTrack = \"201m\"\n}\n\nfunction DDSModule.Init(coreContext)\n    Context = coreContext\n    print(\"[OE-External DDS] Modul Drag Drive Simulator diinisialisasi!\")\nend\n\nfunction DDSModule.HandleCommand(action, payload)\n    if action == \"START_FARM\" then\n        State.IsFarming = true\n        State.Status = \"RACING\"\n        if Context and Context.SendLog then\n            Context.SendLog(\"DDS Auto Race Dimulai!\", \"SUCCESS\")\n        end\n        return true\n\n    elseif action == \"STOP_FARM\" then\n        State.IsFarming = false\n        State.Status = \"STOPPED\"\n        if Context and Context.SendLog then\n            Context.SendLog(\"DDS Auto Race Dihentikan.\", \"WARN\")\n        end\n        return true\n    end\n    return false\nend\n\nfunction DDSModule.GetTelemetry()\n    return {\n        status = State.Status,\n        isFarming = State.IsFarming,\n        tripCount = State.RaceCount,\n        totalEarnings = State.TotalEarnings,\n        currentCash = State.CurrentCoins,\n        currentRoute = State.CurrentTrack\n    }\nend\n\nfunction DDSModule.Cleanup()\n    State.IsFarming = false\n    State.Status = \"STOPPED\"\nend\n\nreturn DDSModule\n\nend\n\nlocal function requireModule(name)\n    if Modules[name] then\n        return Modules[name]()\n    end\n    error(\"[OE-External] Modul tidak ditemukan: \" .. tostring(name))\nend\n\n-- ============================================================================\n-- LOAD CORE SAFETY & KICK DETECTOR\n-- ============================================================================\nlocal Safety = requireModule(\"core/safety\")\nSafety.StartAntiAFK()\n\n-- ============================================================================\n-- DETECT ACTIVE GAME MODULE & PLACE ID\n-- ============================================================================\nlocal placeId = game.PlaceId\nlocal activeGameModule = nil\n\n-- Cek apakah player berada di CDID Main Menu / Lobby (PlaceId: 6911148748)\nlocal pGui = LocalPlayer:FindFirstChild(\"PlayerGui\")\nlocal isLobby = (placeId == 6911148748) or (pGui and pGui:FindFirstChild(\"Hub\") ~= nil)\n\nif isLobby then\n    activeGameModule = requireModule(\"games/cdid_menu\")\nelseif placeId == 110369730911937 then\n    -- Jawa Timur (Tempat Khusus Truck Driver)\n    activeGameModule = requireModule(\"games/cdid\")\nelse\n    -- Map CDID lainnya atau fallback\n    activeGameModule = requireModule(\"games/cdid\")\nend\n\n-- ============================================================================\n-- STATE & WEBSOCKET NETWORKING\n-- ============================================================================\nlocal WS_BASE_URL = \"wss://externalhub.oneeight-project18.workers.dev/ws\"\nlocal WS_URL = string.format(\"%s?role=bot&name=%s&userId=%s&displayName=%s&gameId=%s&gameName=%s&placeId=%s\",\n    WS_BASE_URL,\n    HttpService:UrlEncode(LocalPlayer.Name),\n    tostring(LocalPlayer.UserId),\n    HttpService:UrlEncode(LocalPlayer.DisplayName),\n    HttpService:UrlEncode(activeGameModule.GameId or \"generic\"),\n    HttpService:UrlEncode(activeGameModule.GameName or \"Roblox\"),\n    tostring(placeId)\n)\n\nlocal CoreState = {\n    Socket = nil,\n    BotId = nil,\n    SessionStartTime = os.clock(),\n    FarmActiveSeconds = 0,\n    AutoRejoin = true\n}\n\nlocal function sendPacket(packetType, payload)\n    if not CoreState.Socket then return end\n    pcall(function()\n        local data = HttpService:JSONEncode({\n            type = packetType,\n            payload = payload\n        })\n        CoreState.Socket:Send(data)\n    end)\nend\n\nlocal function sendLog(msg, level)\n    if not CoreState.Socket then return end\n    pcall(function()\n        local data = HttpService:JSONEncode({\n            type = \"LOG\",\n            message = tostring(msg),\n            level = level or \"INFO\"\n        })\n        CoreState.Socket:Send(data)\n    end)\nend\n\n-- Setup Kick Detector Listener\nSafety.InitKickDetector(function(reason)\n    sendLog(\"ROBLOX KICK / DISCONNECT: \" .. tostring(reason), \"ERROR\")\n    sendPacket(\"CLIENT_KICKED\", {\n        reason = reason,\n        placeId = game.PlaceId,\n        autoRejoin = Safety.AutoRejoin,\n        rejoinDelay = Safety.RejoinDelay\n    })\nend)\n\n-- Initialize Active Game Module\nactiveGameModule.Init({\n    SendPacket = sendPacket,\n    SendLog = sendLog,\n    Safety = Safety\n})\n\n-- ============================================================================\n-- WEBSOCKET CONNECTION & COMMAND ROUTING\n-- ============================================================================\nlocal function connectWebSocket()\n    print(\"[OE-External] Menghubungkan ke Hub: \" .. WS_URL)\n    local ok, ws = pcall(function()\n        if WebSocket and typeof(WebSocket.connect) == \"function\" then\n            return WebSocket.connect(WS_URL)\n        elseif syn and syn.websocket and typeof(syn.websocket.connect) == \"function\" then\n            return syn.websocket.connect(WS_URL)\n        end\n        error(\"Executor tidak mendukung WebSocket API\")\n    end)\n\n    if not ok or not ws then\n        warn(\"[OE-External] Gagal membuka WebSocket: \" .. tostring(ws))\n        task.wait(5)\n        if _G.OE_ExternalRunning then return connectWebSocket() end\n        return\n    end\n\n    CoreState.Socket = ws\n    _G.OE_ExternalSocket = ws\n    print(\"[OE-External] WebSocket terhubung sukses!\")\n\n    ws.OnMessage:Connect(function(msgRaw)\n        local okParse, data = pcall(function() return HttpService:JSONDecode(msgRaw) end)\n        if not okParse or not data then return end\n\n        if data.type == \"INIT_ACK\" then\n            CoreState.BotId = data.botId\n            print(\"[OE-External] Terdaftar dengan Bot ID: \" .. tostring(CoreState.BotId))\n            sendLog(string.format(\"Akun aktif di %s (%s) & terhubung ke Web Hub!\", activeGameModule.GameName, tostring(game.PlaceId)), \"SUCCESS\")\n\n        elseif data.type == \"EXECUTE_COMMAND\" then\n            local action = data.action\n            local payload = data.payload or {}\n            print(\"[OE-External] Menerima Perintah: \" .. tostring(action))\n\n            if action == \"REJOIN_SERVER\" then\n                sendLog(\"Menerima perintah Rejoin Server...\", \"WARN\")\n                Safety.RejoinNow()\n\n            elseif action == \"TOGGLE_AUTO_REJOIN\" then\n                Safety.AutoRejoin = not Safety.AutoRejoin\n                sendLog(\"Auto-Rejoin saat kick: \" .. (Safety.AutoRejoin and \"AKTIF\" or \"NONAKTIF\"), \"INFO\")\n\n            else\n                local handled = activeGameModule.HandleCommand(action, payload)\n                if not handled then\n                    sendLog(\"Perintah tidak dikenali oleh modul game: \" .. tostring(action), \"WARN\")\n                end\n            end\n        end\n    end)\n\n    ws.OnClose:Connect(function()\n        warn(\"[OE-External] WebSocket terputus! Mencoba rekoneksi dalam 3 detik...\")\n        CoreState.Socket = nil\n        task.wait(3)\n        if _G.OE_ExternalRunning and not Safety.IsKicked then\n            connectWebSocket()\n        end\n    end)\nend\n\n-- ============================================================================\n-- TELEMETRY STREAM LOOP (1 Detik Sekali)\n-- ============================================================================\ntask.spawn(function()\n    while _G.OE_ExternalRunning do\n        local sessionSeconds = math.floor(os.clock() - CoreState.SessionStartTime)\n        local h = math.floor(sessionSeconds / 3600)\n        local m = math.floor((sessionSeconds % 3600) / 60)\n        local s = math.floor(sessionSeconds % 60)\n        local sessionTimeFormatted = string.format(\"%02d:%02d:%02d\", h, m, s)\n\n        local gameTelem = activeGameModule.GetTelemetry() or {}\n        if gameTelem.isFarming and not Safety.IsKicked then\n            CoreState.FarmActiveSeconds = CoreState.FarmActiveSeconds + 1\n        end\n        local fSec = CoreState.FarmActiveSeconds\n        local fh = math.floor(fSec / 3600)\n        local fm = math.floor((fSec % 3600) / 60)\n        local fs = math.floor(fSec % 60)\n        local farmTimeFormatted = string.format(\"%02d:%02d:%02d\", fh, fm, fs)\n\n        local combinedPayload = {\n            sessionTime = sessionTimeFormatted,\n            sessionSeconds = sessionSeconds,\n            farmActiveTime = farmTimeFormatted,\n            farmActiveSeconds = fSec,\n            isKicked = Safety.IsKicked,\n            kickReason = Safety.KickReason,\n            autoRejoin = Safety.AutoRejoin,\n            gameId = activeGameModule.GameId,\n            gameName = activeGameModule.GameName,\n            currencyUnit = activeGameModule.CurrencyUnit,\n            metricUnit = activeGameModule.MetricUnit,\n            placeId = tostring(game.PlaceId)\n        }\n\n        for k, v in pairs(gameTelem) do\n            combinedPayload[k] = v\n        end\n\n        sendPacket(\"TELEMETRY\", combinedPayload)\n        task.wait(1.0)\n    end\nend)\n\nconnectWebSocket()\n";

export function getAgentLuaCode(origin) {
  const wsUrl = (origin || "https://externalhub.oneeight-project18.workers.dev").replace(/^http/, "ws") + "/ws";
  return AGENT_LUA.replace("wss://externalhub.oneeight-project18.workers.dev/ws", wsUrl);
}
